# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DÜZGÜN ÇEMBERSEL HAREKETTE VEKTÖRLER VE BAĞINTILAR</text>\n  <rect x="20" y="45" width="320" height="185" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">YÖRÜNGE VE VEKTÖR YÖNLERİ</text>\n  <circle cx="155" cy="145" r="62" fill="#ffffff" stroke="#1d4ed8" stroke-width="2" stroke-dasharray="5,3"/>\n  <circle cx="155" cy="145" r="4" fill="#0f172a"/>\n  <text x="143" y="150" font-size="11" font-weight="bold" fill="#0f172a">O</text>\n  <line x1="155" y1="145" x2="217" y2="145" stroke="#2563eb" stroke-width="2.5"/>\n  <polygon points="217,145 209,141 209,149" fill="#2563eb"/>\n  <text x="185" y="160" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">r (Konum)</text>\n  <circle cx="217" cy="145" r="5" fill="#dc2626"/>\n  <line x1="217" y1="145" x2="217" y2="88" stroke="#16a34a" stroke-width="2.5"/>\n  <polygon points="217,85 213,93 221,93" fill="#16a34a"/>\n  <text x="242" y="98" font-size="10.5" font-weight="bold" fill="#15803d">v (Teğet Hız)</text>\n  <line x1="212" y1="140" x2="172" y2="140" stroke="#dc2626" stroke-width="2.5"/>\n  <polygon points="168,140 176,136 176,144" fill="#dc2626"/>\n  <text x="190" y="132" text-anchor="middle" font-size="10" font-weight="bold" fill="#dc2626">F, a (Merkeze)</text>\n  <text x="180" y="220" text-anchor="middle" font-size="9.5" fill="#334155">Hız vektörü (v) yarıçap vektörüne (r) daima diktir (v ⊥ r).</text>\n\n  <rect x="360" y="45" width="320" height="185" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">PERİYOT VE FREKANS İLİŞKİSİ</text>\n  <rect x="375" y="80" width="290" height="62" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Periyot (T): 1 tam tur süresi (Birim: s)</text>\n  <text x="520" y="116" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Frekans (f): 1 saniyedeki tur sayısı (Birim: Hz = 1/s)</text>\n  <text x="520" y="134" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Temel Bağıntı: T · f = 1</text>\n  <rect x="375" y="150" width="290" height="66" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="520" y="168" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">Kasnak ve Dişli Sistemleri:</text>\n  <text x="520" y="185" text-anchor="middle" font-size="9.5" fill="#334155">• Eş merkezli kasnaklarda: T, f ve ω eşittir.</text>\n  <text x="520" y="202" text-anchor="middle" font-size="9.5" fill="#334155">• Kayışla bağlı farklı kasnaklarda: Çizgisel sürat (v) eşittir.</text>\n</svg>', '<svg viewBox="0 0 700 230" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="230" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ÇİZGİSEL HIZ (v) VE AÇISAL HIZ (ω) KARŞILAŞTIRMASI</text>\n  <rect x="20" y="48" width="320" height="162" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="2"/>\n  <text x="180" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">ÇİZGİSEL HIZ (v)</text>\n  <rect x="35" y="82" width="290" height="114" rx="6" fill="#ffffff" stroke="#6366f1" stroke-width="1.2"/>\n  <text x="180" y="102" text-anchor="middle" font-size="10" fill="#334155">• Tanım: Birim zamanda çember yayında alınan yol.</text>\n  <text x="180" y="122" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#4338ca">Formül: v = 2·π·r / T = 2·π·r·f</text>\n  <text x="180" y="142" text-anchor="middle" font-size="10" fill="#334155">• Birim: metre/saniye (m/s)</text>\n  <text x="180" y="162" text-anchor="middle" font-size="10" fill="#334155">• Yönü: Yörüngeye her an teğettir ve değişir.</text>\n  <text x="180" y="182" text-anchor="middle" font-size="10" font-weight="bold" fill="#3730a3">Geçiş Bağıntısı: v = ω · r</text>\n\n  <rect x="360" y="48" width="320" height="162" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">AÇISAL HIZ (ω)</text>\n  <rect x="375" y="82" width="290" height="114" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.2"/>\n  <text x="520" y="102" text-anchor="middle" font-size="10" fill="#334155">• Tanım: Yarıçap vektörünün birim zamanda taradığı açı.</text>\n  <text x="520" y="122" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Formül: ω = 2·π / T = 2·π·f</text>\n  <text x="520" y="142" text-anchor="middle" font-size="10" fill="#334155">• Birim: radyan/saniye (rad/s)</text>\n  <text x="520" y="162" text-anchor="middle" font-size="10" fill="#334155">• Yönü: Sağ el kuralı ile bulunur, düzleme diktir.</text>\n  <text x="520" y="182" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">Yarıçapa (r) doğrudan bağlı değildir!</text>\n</svg>', '<svg viewBox="0 0 700 220" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="220" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MERKEZCİL İVME VE MERKEZCİL KUVVET MODELLERİ</text>\n  <rect x="20" y="48" width="320" height="152" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">MERKEZCİL İVME (a)</text>\n  <rect x="35" y="82" width="290" height="104" rx="6" fill="#ffffff" stroke="#f87171" stroke-width="1.2"/>\n  <text x="180" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">a = v² / r = ω² · r = (4·π²·r) / T²</text>\n  <text x="180" y="124" text-anchor="middle" font-size="10" fill="#334155">• Hızın büyüklüğünü değil, yönünü değiştirir.</text>\n  <text x="180" y="144" text-anchor="middle" font-size="10" fill="#334155">• Yönü her an çemberin merkezine doğrudur.</text>\n  <text x="180" y="164" text-anchor="middle" font-size="10" fill="#334155">• Konum vektörü (r) ile zıt yönlüdür (a = -ω²·r).</text>\n\n  <rect x="360" y="48" width="320" height="152" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">MERKEZCİL KUVVET (F = m · a)</text>\n  <rect x="375" y="82" width="290" height="104" rx="6" fill="#ffffff" stroke="#a855f7" stroke-width="1.2"/>\n  <text x="520" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">F = (m · v²) / r = m · ω² · r</text>\n  <text x="520" y="124" text-anchor="middle" font-size="10" fill="#334155">• Merkeze doğru olan NET KUVVETİN adıdır.</text>\n  <text x="520" y="144" text-anchor="middle" font-size="10" fill="#334155">• Serbest cisim diyagramında ayrıca gösterilmez!</text>\n  <text x="520" y="164" text-anchor="middle" font-size="10" fill="#334155">• İp koparsa cisim o anki hız (v) yönünde teğet fırlar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
